/* generado por prompts/herramientas/clave-tests.js; no editar a mano */
(window.CLAVE_TODO=window.CLAVE_TODO||{})[7]=[{"a":"Artículo 2 — Ámbito de protección y consentimiento ✱","q":[{"i":"7-5","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Disposiciones Generales. El consentimiento del titular del derecho será revocable en cualquier momento:","o":["No indemnizando en su caso, los daños y perjuicios causados.","Pudiendo indemnizar en su caso, los daños y perjuicios causados, pero no las expectativas justificadas.","Pero habrán de indemnizarse en caso, los daños y perjuicios causados, incluyendo en ellos cualquier tipo de expectativas.","Pero habrán de indemnizarse, en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Pero habrán de indemnizarse, en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas</mark></span>Son expectativas JUSTIFICADAS, no «cualquier tipo de expectativas». Según el <span class=\"ref-norma\">art. 2.3 de la LO 1/1982</span>: <span class=\"ref-concepto\">\"El consentimiento a que se refiere el párrafo anterior será revocable en cualquier momento, pero habrán de indemnizarse en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7311","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. La protección civil del honor, de la intimidad y de la propia imagen quedará delimitada por las leyes y por los usos sociales atendiendo:","o":["al criterio exclusivo del juez en cada caso.","a la notoriedad pública de cada persona.","al ámbito que, por sus propios actos, mantenga cada persona reservado para sí misma o su familia.","a los criterios de los códigos deontológicos profesionales, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al ámbito que, por sus propios actos, mantenga cada persona reservado para sí misma o su familia</mark></span>El <span class=\"ref-norma\">art. 2.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"delimitada por las leyes y por los usos sociales atendiendo al ámbito que, por sus propios\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7312","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. No se apreciará la existencia de intromisión ilegítima en el ámbito protegido cuando estuviere expresamente autorizada por Ley o cuando el titular del derecho hubiere otorgado su consentimiento:","o":["tácito.","expreso.","verbal.","presunto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">expreso</mark></span>El <span class=\"ref-norma\">art. 2.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando el titular del derecho hubiere otorgado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7313","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. Tampoco se apreciará intromisión ilegítima, por imperativo de la Constitución, cuando se trate de:","o":["opiniones manifestadas por Diputados o Senadores en el ejercicio de sus funciones.","opiniones manifestadas por miembros del Gobierno en el ejercicio de sus funciones, sin perjuicio de lo dispuesto en el Derecho nacional.","opiniones manifestadas por Magistrados en sus resoluciones.","opiniones manifestadas por miembros de las Asambleas autonómicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">opiniones manifestadas por Diputados o Senadores en el ejercicio de sus funciones</mark></span>El <span class=\"ref-norma\">art. 2.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando se trate de opiniones manifestadas por Diputados o Senadores en el ejercicio\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7314","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. El consentimiento del titular del derecho será revocable en cualquier momento, pero habrán de indemnizarse, en su caso:","o":["los daños materiales causados, excluyendo el lucro cesante, en los términos que establezca el propio Reglamento.","los gastos de publicidad realizados.","los daños morales exclusivamente.","los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas</mark></span>El <span class=\"ref-norma\">art. 2.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"pero habrán de indemnizarse en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional","q":[{"i":"7-7","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las peticiones de indemnización, que se sustanciarán por el trámite de los incidentes, deberán presentarse dentro del plazo de _______ a partir de la publicación de la sentencia del Tribunal Constitucional.","o":["Un mes.","Tres meses.","Seis meses.","Un año."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un año</mark></span>Según el <span class=\"ref-norma\">art. 58.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las peticiones de indemnización [...] deberán presentarse dentro del plazo de un año a partir de la publicación de la sentencia del Tribunal Constitucional\"</span> (verificado con el texto del temario)."},{"i":"7-53","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes: Señale la opción correcta.","o":["Al menos, dos tercios de los miembros que en cada momento lo compongan.","Más de dos tercios de los miembros que componen el Pleno.","Como mínimo tres quintos de los miembros que compongan cada una de las Salas.","En todo caso, tres quintos de los miembros definidos en el artículo 5 de esta Ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al menos, dos tercios de los miembros que en cada momento lo compongan</mark></span>El <span class=\"ref-norma\">art. 14 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes, al menos, dos tercios de los miembros que en cada momento lo compongan.\"</span>."},{"i":"7-56","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Recurso de amparo. Será competente para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión: Señale la respuesta correcta.","o":["Los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas.","El letrado de la Administración de Justicia del Tribunal Constitucional.","El Presidente de la Sección que conozca del asunto.","El Magistrado-Ponente que conozca del asunto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas</mark></span>Según el <span class=\"ref-norma\">art. 58.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Serán competentes para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas\"</span> (verificado con el texto del temario)."},{"i":"7-58","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Quién nombra al Presidente del Tribunal Constitucional?","o":["El Consejo de Estado.","El Ministro de Justicia.","El Rey.","El Tribunal en Pleno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Rey</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El nombre del elegido se elevará al Rey para su nombramiento por un período de tres años, expirado el cual podrá ser reelegido por una sola vez.\"</span>."},{"i":"7-63","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿De qué forma se encajan los presupuestos del Tribunal Constitucional en los Presupuestos Generales del Estado?","o":["Se integra como una sección independiente dentro de los Presupuestos Generales del Estado.","Se integra como una sección dependiente dentro de los Presupuestos Generales del Estado.","Se integra de forma genérica en los Presupuestos Generales del Estado.","No se encuentran integrados en los Presupuestos Generales del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se integra como una sección independiente dentro de los Presupuestos Generales del Estado</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>."},{"i":"7-82","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Los acuerdos de las Secciones requerirán la presencia de:","o":["Cuatro miembros, salvo que exista discrepancia, requiriéndose entonces la de cinco miembros.","Dos tercios de los miembros que en cada momento la compongan.","La mitad de los miembros que en cada momento la compongan.","Dos miembros, salvo que exista discrepancia, requiriéndose entonces la de tres miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Dos miembros, salvo que exista discrepancia, requiriéndose entonces la de tres miembros</mark></span>Las Secciones tienen tres miembros (el Presidente o quien le sustituya y dos Magistrados). Según el <span class=\"ref-norma\">art. 14 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"En las Secciones se requerirá la presencia de dos miembros, salvo que haya discrepancia, requiriéndose entonces la de sus tres miembros\"</span> (verificado con el texto del temario)."},{"i":"7-83","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes:","o":["Al menos, un tercio de sus miembros.","Al menos, un cuarto de sus miembros.","Al menos, un quinto de sus miembros.","Al menos, dos tercios de sus miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al menos, dos tercios de sus miembros</mark></span>El <span class=\"ref-norma\">art. 14 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes, al menos, dos tercios de los miembros que en cada momento lo compongan.\"</span>."},{"i":"7-87","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Cuál de las siguientes funciones NO se atribuye al Presidente del Tribunal Constitucional?","o":["Ejerce la representación del Tribunal.","Aprueba los presupuestos.","Convoca las Salas.","Adopta medidas precisas para el funcionamiento de las Secciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Aprueba los presupuestos</mark></span>Los presupuestos los elabora el Tribunal en Pleno (art. 10.3), no el Presidente. Según el <span class=\"ref-norma\">art. 15 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas; adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones [...]\"</span> (verificado con el texto del temario)."},{"i":"7-93","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. En relación con la tramitación de los recursos de amparo constitucional: señale la INCORRECTA.","o":["Las providencias de inadmisión, solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días.","Cuando en la demanda de amparo concurran uno o varios defectos de subsanables, de no producirse la subsanación dentro del plazo fijado en dicho precepto, la Sección acordará la inadmisión mediante providencia, contra la cual no cabrá recurso alguno.","Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que emanó la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en un plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.","El órgano, la autoridad, Juez o Tribunal avocará de inmediato del requerimiento, cumplimentará el envío dentro del plazo y limitará a emplazar a quienes fueron parte en el procedimiento antecedente para que puedan comparecer en el proceso constitucional en el plazo de diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El órgano, la autoridad, Juez o Tribunal avocará de inmediato del requerimiento, cumplimentará el envío dentro del plazo y limitará a emplazar a quienes fueron parte en el procedimiento antecedente para que puedan comparecer en el proceso constitucional en el plazo de diez días</mark></span>«Avocará» y «se limitará a emplazar» alteran el texto (acusa recibo, cumplimenta el envío y emplaza). Según el <span class=\"ref-norma\">art. 51 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El órgano, autoridad, Juez o Tribunal acusará inmediato recibo del requerimiento, cumplimentará el envío dentro del plazo señalado y emplazará a quienes fueron parte en el procedimiento antecedente\"</span> (verificado con el texto del temario)."},{"i":"7-116","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal en Pleno conoce de los siguientes asuntos, entre otros: señale la INCORRECTA.","o":["De los recursos de inconstitucionalidad contra las leyes y demás disposiciones con valor de ley, incluidos los de mera aplicación de doctrina.","De las cuestiones de constitucionalidad que reserve para sí; las demás deberán deferirse a las Salas según un turno objetivo.","De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de las de éstas entre sí.","De los conflictos en defensa de la autonomía local."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De los recursos de inconstitucionalidad contra las leyes y demás disposiciones con valor de ley, incluidos los de mera aplicación de doctrina</mark></span>El <span class=\"ref-norma\">art. 10.1.b) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) De los recursos de inconstitucionalidad contra las leyes y demás disposiciones con valor de ley, excepto los de mera aplicación de doctrina, cuyo conocimiento podrá atribuirse a las Salas en el trámite de admisión.\"</span>. La opción A dice «inclusive» los de mera aplicación de doctrina, cuando la ley los EXCEPTÚA; por eso es la incorrecta."},{"i":"7-124","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que emanó la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en un plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.","o":["En el plazo que no podrá exceder de diez días.","En el plazo que no podrá exceder de veinte días.","En el plazo que no podrá exceder de quince días.","En el plazo que no podrá exceder de cinco días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo que no podrá exceder de diez días</mark></span>El <span class=\"ref-norma\">art. 51.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.\"</span>."},{"i":"7-136","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal en Pleno elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento. El nombre del elegido se elevará al Rey para su nombramiento por un periodo de:","o":["Tres años, y podrá ser reelegido por una sola vez.","Tres años y no podrá ser reelegido.","Cinco años y podrá ser reelegido.","Cinco años y no podrá ser reelegido."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres años, y podrá ser reelegido por una sola vez</mark></span>Según el <span class=\"ref-norma\">art. 9.3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El nombre del elegido se elevará al Rey para su nombramiento por un período de tres años, expirado el cual podrá ser reelegido por una sola vez\"</span> (verificado con el texto del temario)."},{"i":"7-142","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. Las resoluciones del Tribunal Constitucional:","o":["Podrán ser enjuiciadas por el Tribunal Supremo cuando afecten a la legalidad ordinaria.","Podrán ser revisadas por el Pleno del Consejo General del Poder Judicial.","Solo podrán ser enjuiciadas por el Tribunal Europeo de Derechos Humanos.","No podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las resoluciones del Tribunal Constitucional no podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-143","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal en Pleno conoce de cualquier otro asunto que sea competencia del Tribunal pero recabe para sí el Pleno, a propuesta de:","o":["El Presidente o de tres Magistrados.","El Presidente o de dos Magistrados.","El Vicepresidente o de tres Magistrados.","La mayoría absoluta de los Magistrados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Presidente o de tres Magistrados</mark></span>El <span class=\"ref-norma\">art. 10.1.n) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"n) De cualquier otro asunto que sea competencia del Tribunal pero recabe para sí el Pleno, a propuesta del Presidente o de tres Magistrados\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-144","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. Las violaciones de los derechos y libertades originadas por disposiciones, actos jurídicos, omisiones o simple vía de hecho del Gobierno o de sus autoridades o funcionarios, o de los órganos ejecutivos colegiados de las comunidades autónomas o de sus autoridades o funcionarios o agentes, podrán dar lugar al recurso de amparo:","o":["En el plazo de tres meses desde que sean firmes.","Directamente, sin necesidad de agotar la vía judicial.","Una vez que se haya agotado la vía judicial procedente.","Una vez agotada la vía administrativa previa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una vez que se haya agotado la vía judicial procedente</mark></span>El <span class=\"ref-norma\">art. 43.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán dar lugar al recurso de amparo una vez que se haya agotado la vía judicial procedente\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado EXOF en tu temario)</em>"},{"i":"7-146","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. En el recurso de amparo frente a violaciones originadas por el Gobierno o sus autoridades, el recurso sólo podrá fundarse en la infracción:","o":["Por cualquier acto administrativo de los preceptos legales que desarrollan los derechos fundamentales.","Por una resolución no firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo.","De los Tratados internacionales sobre derechos humanos ratificados por España.","Por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo</mark></span>El <span class=\"ref-norma\">art. 43.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso sólo podrá fundarse en la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-152","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Tribunal en Pleno. El Tribunal en Pleno conoce de las cuestiones de constitucionalidad que reserve para sí; las demás:","o":["Deberán elevarse al Tribunal Supremo para su resolución definitiva.","Se resolverán por la Sección que designe el Presidente en cada caso.","Podrán deferirse a las Salas a propuesta del Fiscal General del Estado.","Deberán deferirse a las Salas según un turno objetivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Deberán deferirse a las Salas según un turno objetivo</mark></span>El <span class=\"ref-norma\">art. 10.1.c) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"c) De las cuestiones de constitucionalidad que reserve para sí; las demás deberán deferirse a las Salas según un turno objetivo.\"</span>"},{"i":"7-153","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Tribunal en Pleno. El Tribunal en Pleno conoce de los conflictos constitucionales de competencia:","o":["Entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.","Entre los órganos constitucionales del Estado y las Comunidades Autónomas.","Entre el Estado y las Entidades locales o de éstas entre sí.","Entre las Comunidades Autónomas y los órganos del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Entre el Estado y las Comunidades Autónomas o de los de éstas entre sí</mark></span>El <span class=\"ref-norma\">art. 10.1.d) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"d) De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.\"</span>"},{"i":"7-ia-7004","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá del recurso de amparo por violación de los derechos y libertades públicos relacionados en:","o":["el artículo cincuenta y tres, uno, de la Constitución.","el artículo cincuenta y tres, dos, de la Constitución.","el artículo ciento sesenta y uno, uno, de la Constitución.","el artículo catorce de la Constitución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el artículo cincuenta y tres, dos, de la Constitución</mark></span>El <span class=\"ref-norma\">art. 2.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo cincuenta y tres, dos, de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7008","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de las impugnaciones previstas en el número dos del artículo ciento sesenta y uno de la Constitución, esto es:","o":["de las leyes y disposiciones con fuerza de ley del Estado.","de las disposiciones y resoluciones adoptadas por los órganos de las Comunidades Autónomas.","de los actos de los Entes locales.","de las resoluciones de los Tribunales Superiores de Justicia, salvo que el Estado miembro afectado disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de las disposiciones y resoluciones adoptadas por los órganos de las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 2.1.f de LOTC</span> dispone: <span class=\"ref-concepto\">\"De las impugnaciones previstas en el número dos del artículo ciento sesenta y uno de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7013","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. El Tribunal Constitucional delimitará el ámbito de su jurisdicción y adoptará cuantas medidas sean necesarias para preservarla, incluyendo:","o":["la declaración de nulidad de aquellos actos o resoluciones que la menoscaben.","la suspensión de los magistrados que la menoscaben, salvo que el Estado miembro afectado disponga otra cosa.","la remisión de testimonio al Ministerio Fiscal.","la apertura de un procedimiento sancionador."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la declaración de nulidad de aquellos actos o resoluciones que la menoscaben</mark></span>El <span class=\"ref-norma\">art. 4.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"incluyendo la declaración de nulidad de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7014","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. Las resoluciones del Tribunal Constitucional:","o":["podrán ser revisadas por el Tribunal Supremo en casación.","podrán ser enjuiciadas por el Tribunal Europeo de Derechos Humanos en todo caso.","podrán ser anuladas por el Pleno del Consejo General del Poder Judicial.","no podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado</mark></span>El <span class=\"ref-norma\">art. 4.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Las resoluciones del Tribunal Constitucional no podrán ser enjuiciadas por ningún\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7015","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. Cuando el Tribunal Constitucional anule un acto o resolución que menoscabe su jurisdicción, lo ha de hacer motivadamente y previa audiencia:","o":["al Gobierno y al órgano autor del acto o resolución.","al Consejo General del Poder Judicial y al Ministerio Fiscal, conforme al procedimiento que se establezca reglamentariamente.","al Ministerio Fiscal y al órgano autor del acto o resolución.","a las partes y al Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Ministerio Fiscal y al órgano autor del acto o resolución</mark></span>El <span class=\"ref-norma\">art. 4.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"lo ha de hacer motivadamente y previa audiencia al Ministerio Fiscal y al órgano autor del acto o resolución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7024","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. El Tribunal en Pleno elige de entre sus miembros a su Presidente por votación:","o":["pública, y propone al Rey su nombramiento, sin perjuicio de lo dispuesto en el Derecho nacional.","secreta, y propone al Rey su nombramiento.","secreta, y lo nombra directamente.","pública, y lo comunica a las Cámaras."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">secreta, y propone al Rey su nombramiento</mark></span>El <span class=\"ref-norma\">art. 9.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7025","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. En la elección del Presidente, en primera votación se requerirá la mayoría absoluta. Si ésta no se alcanzase, se procederá a una segunda votación en la que:","o":["resultará elegido quien obtuviese mayor número de votos.","se exigirá la mayoría de tres quintos.","se exigirá de nuevo la mayoría absoluta.","resultará elegido el Magistrado más antiguo, en los términos que establezca el propio Reglamento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">resultará elegido quien obtuviese mayor número de votos</mark></span>El <span class=\"ref-norma\">art. 9.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en la que resultará elegido quien obtuviese mayor\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7026","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. En caso de empate en la segunda votación para elegir Presidente, se efectuará una última votación y si éste se repitiese, será propuesto:","o":["el de mayor edad y, en caso de igualdad, el más antiguo, salvo que el Estado miembro afectado disponga otra cosa.","el que designe el Rey.","el que decida el Pleno por sorteo.","el de mayor antigüedad en el cargo y, en caso de igualdad, el de mayor edad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el de mayor antigüedad en el cargo y, en caso de igualdad, el de mayor edad</mark></span>El <span class=\"ref-norma\">art. 9.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"será propuesto el de mayor antigüedad en el cargo y en caso de igualdad el de mayor edad\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7027","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. El Presidente del Tribunal Constitucional es nombrado por el Rey por un período de tres años, expirado el cual podrá ser reelegido:","o":["por dos veces.","sin limitación.","por una sola vez.","por una sola vez, con mayoría de dos tercios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por una sola vez</mark></span>El <span class=\"ref-norma\">art. 9.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"por un período de tres años, expirado el cual podrá ser reelegido por una sola vez\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7028","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. El Tribunal en Pleno elegirá entre sus miembros, por el mismo procedimiento y por el mismo período de tres años, un Vicepresidente, al que incumbe:","o":["presidir el Pleno y la Sala Primera.","sustituir al Presidente en caso de vacante, ausencia u otro motivo legal y presidir la Sala Segunda.","convocar las Salas y nombrar a los letrados.","representar al Tribunal ante las Cortes Generales, conforme al procedimiento que se establezca reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sustituir al Presidente en caso de vacante, ausencia u otro motivo legal y presidir la Sala Segunda</mark></span>El <span class=\"ref-norma\">art. 9.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"un Vicepresidente, al que incumbe sustituir al Presidente en caso de vacante, ausencia u otro motivo legal y\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7029","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno conoce de la constitucionalidad o inconstitucionalidad:","o":["de los tratados internacionales.","de los reglamentos del Gobierno.","de los actos de las Cortes Generales.","de los convenios de las Comunidades Autónomas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de los tratados internacionales</mark></span>El <span class=\"ref-norma\">art. 10.1.a de LOTC</span> dispone: <span class=\"ref-concepto\">\"De la constitucionalidad o inconstitucionalidad de los tratados internacionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7030","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno conoce de las cuestiones de constitucionalidad que reserve para sí; las demás deberán deferirse a las Salas:","o":["a propuesta del Presidente.","previo informe del Ministerio Fiscal.","por sorteo entre los Magistrados.","según un turno objetivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">según un turno objetivo</mark></span>El <span class=\"ref-norma\">art. 10.1.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"las demás deberán deferirse a las Salas según un turno objetivo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7031","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno conoce de los recursos previos de inconstitucionalidad contra:","o":["Proyectos de Ley Orgánica y Proyectos de Ley de Presupuestos, sin perjuicio de lo dispuesto en el Derecho nacional.","Proyectos de Decreto-ley y de Decreto legislativo.","Proyectos de Estatutos de Autonomía y contra Propuestas de Reforma de los Estatutos de Autonomía.","Tratados internacionales antes de su ratificación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Proyectos de Estatutos de Autonomía y contra Propuestas de Reforma de los Estatutos de Autonomía</mark></span>El <span class=\"ref-norma\">art. 10.1.d bis de LOTC</span> dispone: <span class=\"ref-concepto\">\"De los recursos previos de inconstitucionalidad contra Proyectos de Estatutos de Autonomía y contra Propuestas de Reforma de los Estatutos de Autonomía\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7032","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Pleno conoce de cualquier otro asunto que sea competencia del Tribunal pero recabe para sí, a propuesta:","o":["del Presidente o de dos Magistrados.","del Presidente o de tres Magistrados.","del Vicepresidente o de un Magistrado.","del Presidente o de cuatro Magistrados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del Presidente o de tres Magistrados</mark></span>El <span class=\"ref-norma\">art. 10.1.n de LOTC</span> dispone: <span class=\"ref-concepto\">\"a propuesta del Presidente o de tres Magistrados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7033","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra:","o":["como una sección independiente dentro de los Presupuestos Generales del Estado.","como un anexo del presupuesto del Consejo General del Poder Judicial, en los términos que establezca el propio Reglamento.","como una partida del Ministerio de Justicia.","como un presupuesto separado aprobado por las Cortes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">como una sección independiente dentro de los Presupuestos Generales del Estado</mark></span>El <span class=\"ref-norma\">art. 10.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"que se integra como una sección independiente dentro de los\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7034","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias de las Salas. Las Salas del Tribunal Constitucional conocerán de los asuntos que, atribuidos a la justicia constitucional, no sean:","o":["de la competencia de las Secciones.","objeto de recurso de amparo.","de la competencia del Presidente.","de la competencia del Pleno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de la competencia del Pleno</mark></span>El <span class=\"ref-norma\">art. 11 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Las Salas del Tribunal Constitucional conocerán de los asuntos que, atribuidos a la justicia constitucional, no sean de la competencia del Pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7037","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Quórum. El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes, al menos, dos tercios de los miembros que en cada momento lo compongan. En las Secciones se requerirá la presencia de dos miembros, salvo que haya discrepancia, requiriéndose entonces:","o":["la de sus tres miembros.","la del Presidente de la Sala.","la de dos tercios de la Sala.","la de todos los miembros de la Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la de sus tres miembros</mark></span>El <span class=\"ref-norma\">art. 14 de LOTC</span> dispone: <span class=\"ref-concepto\">\"salvo que haya discrepancia, requiriéndose entonces la de sus tres miembros\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7039","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. Mediante los procedimientos de declaración de inconstitucionalidad, el Tribunal Constitucional garantiza la primacía de la Constitución y enjuicia:","o":["la legalidad de los reglamentos y actos administrativos.","la compatibilidad de las leyes con el Derecho de la Unión, sin perjuicio de lo dispuesto en el Derecho nacional.","la conformidad o disconformidad con ella de las Leyes, disposiciones o actos impugnados.","la adecuación de las leyes a los tratados internacionales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la conformidad o disconformidad con ella de las Leyes, disposiciones o actos impugnados</mark></span>El <span class=\"ref-norma\">art. 27.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"garantiza la primacía de la Constitución y enjuicia la conformidad o disconformidad con ella de las Leyes, disposiciones o actos impugnados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7040","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. Son susceptibles de declaración de inconstitucionalidad, entre otros:","o":["los reglamentos del Gobierno.","los Reglamentos de las Cámaras y de las Cortes Generales.","las sentencias del Tribunal Supremo.","las resoluciones del Consejo General del Poder Judicial, en los términos que establezca el propio Reglamento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los Reglamentos de las Cámaras y de las Cortes Generales</mark></span>El <span class=\"ref-norma\">art. 27.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"d) Los Reglamentos de las Cámaras y de las Cortes Generales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7041","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. En el caso de los Decretos legislativos, la competencia del Tribunal se entiende sin perjuicio de lo previsto en:","o":["el número seis del artículo ochenta y dos de la Constitución.","el número seis del artículo ochenta y uno de la Constitución, salvo que el Estado miembro afectado disponga otra cosa.","el artículo ochenta y seis de la Constitución.","el artículo ochenta y cuatro de la Constitución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el número seis del artículo ochenta y dos de la Constitución</mark></span>El <span class=\"ref-norma\">art. 27.2.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"la competencia del Tribunal se entiende sin perjuicio de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7042","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. Para apreciar la conformidad o disconformidad con la Constitución de una Ley, el Tribunal considerará, además de los preceptos constitucionales:","o":["los tratados internacionales ratificados por España, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","la jurisprudencia del Tribunal Supremo.","los reglamentos que desarrollen la ley impugnada.","las Leyes que, dentro del marco constitucional, se hubieran dictado para delimitar las competencias del Estado y las Comunidades Autónomas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las Leyes que, dentro del marco constitucional, se hubieran dictado para delimitar las competencias del Estado y las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 28.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las Leyes que, dentro del marco constitucional, se hubieran dictado para delimitar las competencias del Estado y las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7043","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. El Tribunal podrá declarar inconstitucionales los preceptos de un Decreto-ley, Decreto legislativo o Ley no orgánica que regulen materias reservadas a Ley Orgánica, por infracción:","o":["del artículo ochenta y dos de la Constitución.","del artículo ochenta y cuatro de la Constitución.","del artículo ochenta y uno de la Constitución.","del artículo ochenta y seis de la Constitución."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">del artículo ochenta y uno de la Constitución</mark></span>El <span class=\"ref-norma\">art. 28.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"por infracción del artículo ochenta y uno de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7046","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. La admisión de un recurso o de una cuestión de inconstitucionalidad no suspenderá la vigencia ni la aplicación de la Ley, excepto en el caso en que:","o":["la Ley impugnada sea una Ley Orgánica.","el recurrente sea el Defensor del Pueblo.","la Ley impugnada afecte a derechos fundamentales, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento.","el Gobierno se ampare en lo dispuesto por el artículo ciento sesenta y uno, dos, de la Constitución para impugnar, por medio de su Presidente, disposiciones de las Comunidades Autónomas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Gobierno se ampare en lo dispuesto por el artículo ciento sesenta y uno, dos, de la Constitución para impugnar, por medio de su Presidente, disposiciones de las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 30 de LOTC</span> dispone: <span class=\"ref-concepto\">\"excepto en el caso en que el Gobierno se ampare en lo dispuesto por el artículo ciento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7050","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. El recurso de inconstitucionalidad se formulará dentro del plazo de:","o":["dos meses a partir de la publicación de la Ley impugnada.","seis meses a partir de la publicación de la Ley impugnada, conforme al procedimiento que se establezca reglamentariamente.","un mes a partir de la publicación de la Ley impugnada.","tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado</mark></span>El <span class=\"ref-norma\">art. 33.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"se formulará dentro del plazo de tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7051","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. El Presidente del Gobierno y los órganos colegiados ejecutivos de las Comunidades Autónomas podrán interponer el recurso en el plazo de nueve meses cuando, con la finalidad de evitar la interposición del recurso, se cumplan determinados requisitos, entre ellos:","o":["que se reúna la Conferencia de Presidentes.","que se reúna la Comisión General de las Comunidades Autónomas del Senado, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento.","que se reúna la Comisión Bilateral de Cooperación entre la Administración General del Estado y la respectiva Comunidad Autónoma.","que se obtenga un informe del Consejo de Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">que se reúna la Comisión Bilateral de Cooperación entre la Administración General del Estado y la respectiva Comunidad Autónoma</mark></span>El <span class=\"ref-norma\">art. 33.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Que se reúna la Comisión Bilateral de Cooperación entre la Administración General\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7052","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. Uno de los requisitos para el plazo de nueve meses es que el acuerdo de la Comisión Bilateral sea puesto en conocimiento del Tribunal Constitucional dentro de:","o":["los treinta días siguientes a la publicación de la Ley, salvo que el Estado miembro afectado disponga otra cosa.","los tres meses siguientes a la publicación de la Ley, disposición o acto con fuerza de Ley.","los seis meses siguientes a la publicación de la Ley.","los quince días siguientes a la reunión de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los tres meses siguientes a la publicación de la Ley, disposición o acto con fuerza de Ley</mark></span>El <span class=\"ref-norma\">art. 33.2.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"dentro de los tres meses siguientes a la publicación de la\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7054","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Cuando un Juez o Tribunal considere que una norma con rango de Ley aplicable al caso y de cuya validez dependa el fallo pueda ser contraria a la Constitución, podrá plantear la cuestión:","o":["únicamente de oficio.","únicamente a instancia del Ministerio Fiscal.","previa autorización del Consejo General del Poder Judicial.","de oficio o a instancia de parte."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de oficio o a instancia de parte</mark></span>El <span class=\"ref-norma\">art. 35.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"de oficio o a instancia de parte, considere que una\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7059","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El órgano judicial elevará al Tribunal Constitucional la cuestión de inconstitucionalidad junto con:","o":["copia de la sentencia dictada en primera instancia, conforme al procedimiento que se establezca reglamentariamente.","informe del Ministerio Fiscal.","testimonio de los autos principales y de las alegaciones previstas, si las hubiere.","dictamen del Consejo de Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">testimonio de los autos principales y de las alegaciones previstas, si las hubiere</mark></span>El <span class=\"ref-norma\">art. 36 de LOTC</span> dispone: <span class=\"ref-concepto\">\"junto con testimonio de los autos principales y de las alegaciones previstas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7063","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. Señale la INCORRECTA sobre las competencias del Pleno del Tribunal Constitucional:","o":["Conoce de los conflictos entre los órganos constitucionales del Estado, sin perjuicio de lo dispuesto en el Derecho nacional.","Conoce de la recusación de los Magistrados del Tribunal Constitucional.","Conoce de los recursos de amparo salvo los de mera aplicación de doctrina.","Aprueba y modifica los reglamentos del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Conoce de los recursos de amparo salvo los de mera aplicación de doctrina</mark></span>El <span class=\"ref-norma\">art. 10 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"g) De los conflictos entre los órganos constitucionales del Estado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7064","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. Señale la INCORRECTA sobre el plazo del recurso de inconstitucionalidad:","o":["El plazo general es de tres meses desde la publicación de la norma.","El plazo general es de seis meses desde la publicación de la norma.","El plazo especial es de nueve meses para el Presidente del Gobierno y los órganos ejecutivos autonómicos si se cumplen los requisitos.","Los demás legitimados pueden recurrir en el plazo general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El plazo general es de seis meses desde la publicación de la norma</mark></span>El <span class=\"ref-norma\">art. 33 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"se formulará dentro del plazo de tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7151","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. Las sentencias recaídas en procedimientos de inconstitucionalidad tendrán el valor de cosa juzgada, vincularán a todos los Poderes Públicos y producirán efectos generales:","o":["desde la fecha de su publicación en el «Boletín Oficial del Estado».","desde la fecha de su notificación a las partes.","desde la fecha de su aprobación por el Pleno.","desde la fecha de entrada en vigor de la ley impugnada, en los términos que establezca el propio Reglamento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">desde la fecha de su publicación en el «Boletín Oficial del Estado»</mark></span>El <span class=\"ref-norma\">art. 38.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"producirán efectos generales desde la fecha de su publicación en el «Boletín Oficial del Estado»\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7152","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. Las sentencias desestimatorias dictadas en recursos de inconstitucionalidad y en conflictos en defensa de la autonomía local impedirán cualquier planteamiento ulterior de la cuestión por cualquiera de las dos vías, siempre que esté:","o":["fundado en el mismo recurrente.","fundado en una norma de idéntico rango.","fundado en el mismo plazo de impugnación, salvo que el Estado miembro afectado disponga otra cosa.","fundado en la misma infracción de idéntico precepto constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">fundado en la misma infracción de idéntico precepto constitucional</mark></span>El <span class=\"ref-norma\">art. 38.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"fundado en la misma infracción de idéntico precepto constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7154","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. El Juez o Tribunal quedará vinculado a la sentencia constitucional desde que tuviere conocimiento de ella, y las partes:","o":["desde la fecha de su publicación.","desde el momento en que sean notificadas.","desde que el Tribunal Constitucional la comunique al Ministerio Fiscal.","desde que adquiera firmeza."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">desde el momento en que sean notificadas</mark></span>El <span class=\"ref-norma\">art. 38.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las partes desde el momento en que sean notificadas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7157","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de las sentencias de inconstitucionalidad. Las sentencias declaratorias de la inconstitucionalidad no permitirán revisar procesos fenecidos mediante sentencia con fuerza de cosa juzgada, salvo en el caso de:","o":["los procesos civiles en los que se haya aplicado la norma inconstitucional, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","los procesos laborales en los que se hayan reconocido derechos.","los procesos penales o contencioso-administrativos referentes a un procedimiento sancionador en que, como consecuencia de la nulidad de la norma aplicada, resulte una reducción de la pena o de la sanción o una exclusión, exención o limitación de la responsabilidad.","los procesos penales en los que se haya impuesto una pena de prisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los procesos penales o contencioso-administrativos referentes a un procedimiento sancionador en que, como consecuencia de la nulidad de la norma aplicada, resulte una reducción de la pena o de la sanción o una exclusión, exención o limitación de la responsabilidad</mark></span>El <span class=\"ref-norma\">art. 40.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"salvo en el caso de los procesos penales o contencioso-\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7158","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de las sentencias de inconstitucionalidad. La jurisprudencia de los tribunales de justicia recaída sobre leyes, disposiciones o actos enjuiciados por el Tribunal Constitucional habrá de entenderse:","o":["vinculante para el Tribunal Constitucional.","corregida por la doctrina derivada de las sentencias y autos que resuelvan los procesos constitucionales.","prevalente sobre la doctrina constitucional en materia de legalidad ordinaria, sin perjuicio de lo dispuesto en el Derecho nacional.","suspendida hasta la publicación de la sentencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">corregida por la doctrina derivada de las sentencias y autos que resuelvan los procesos constitucionales</mark></span>El <span class=\"ref-norma\">art. 40.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"habrá de entenderse corregida por la doctrina derivada de las sentencias y autos que resuelvan los procesos constitucionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7163","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. Las violaciones de derechos originadas por actos del Gobierno o de sus autoridades o funcionarios podrán dar lugar al recurso de amparo:","o":["una vez que se haya agotado la vía judicial procedente.","en cualquier momento, sin necesidad de agotar la vía previa.","una vez interpuesto recurso de alzada.","previa solicitud de informe al Defensor del Pueblo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una vez que se haya agotado la vía judicial procedente</mark></span>El <span class=\"ref-norma\">art. 43.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán dar lugar al recurso de amparo una vez que se haya agotado la vía judicial procedente\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7165","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. En el amparo frente a actos del Gobierno, el recurso solo podrá fundarse en:","o":["la infracción de cualquier precepto de la Constitución.","la infracción de una norma de legalidad ordinaria.","la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo.","la infracción de los tratados internacionales sobre derechos humanos, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo</mark></span>El <span class=\"ref-norma\">art. 43.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso sólo podrá fundarse en la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7183","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del amparo. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de:","o":["diez días, remita las actuaciones o testimonio de ellas.","cinco días, remita las actuaciones o testimonio de ellas.","quince días, remita las actuaciones o testimonio de ellas.","veinte días, remita las actuaciones o testimonio de ellas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez días, remita las actuaciones o testimonio de ellas</mark></span>El <span class=\"ref-norma\">art. 51.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7184","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del amparo. El órgano, autoridad, Juez o Tribunal acusará inmediato recibo del requerimiento, cumplimentará el envío dentro del plazo señalado y emplazará a quienes fueron parte en el procedimiento antecedente para que puedan comparecer en el proceso constitucional en el plazo de:","o":["cinco días.","quince días.","veinte días.","diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">diez días</mark></span>El <span class=\"ref-norma\">art. 51.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"para que puedan comparecer en el proceso constitucional en el plazo de diez días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7189","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Resolución del amparo. Cuando la Sala conozca del recurso de amparo respecto de decisiones de jueces y tribunales, limitará su función a concretar si se han violado derechos o libertades del demandante y a preservar o restablecer estos derechos, y se abstendrá:","o":["de pronunciarse sobre la imposición de costas.","de conocer de recursos contra resoluciones del Tribunal Supremo, salvo que el Estado miembro afectado disponga otra cosa.","de cualquier otra consideración sobre la actuación de los órganos jurisdiccionales.","de cualquier consideración sobre los hechos probados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de cualquier otra consideración sobre la actuación de los órganos jurisdiccionales</mark></span>El <span class=\"ref-norma\">art. 54 de LOTC</span> dispone: <span class=\"ref-concepto\">\"y se abstendrá de cualquier otra consideración sobre la actuación de los órganos jurisdiccionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7198","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Modificación de la suspensión. La suspensión o su denegación puede ser modificada durante el curso del juicio de amparo constitucional, de oficio o a instancia de parte, en virtud de:","o":["un cambio de doctrina del Tribunal Constitucional.","circunstancias sobrevenidas o que no pudieron ser conocidas al tiempo de sustanciarse el incidente de suspensión.","la presentación de nueva documentación por el recurrente, conforme al procedimiento que se establezca reglamentariamente.","la petición del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">circunstancias sobrevenidas o que no pudieron ser conocidas al tiempo de sustanciarse el incidente de suspensión</mark></span>El <span class=\"ref-norma\">art. 57 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en virtud de circunstancias sobrevenidas o que no pudieron ser conocidas al tiempo de sustanciarse el incidente de suspensión\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7199","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Indemnización por la suspensión. Serán competentes para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión:","o":["los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas.","el propio Tribunal Constitucional, sin perjuicio de lo dispuesto en el Derecho nacional.","el Consejo de Estado.","la Administración demandada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas</mark></span>El <span class=\"ref-norma\">art. 58.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Serán competentes para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión los Jueces o Tribunales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7201","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. Señale la INCORRECTA sobre el recurso de amparo frente a violaciones originadas por el Gobierno o sus autoridades:","o":["Exige haber agotado la vía judicial procedente.","El plazo es de veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","Puede interponerse sin necesidad de agotar la vía judicial procedente.","Solo puede fundarse en la infracción de preceptos constitucionales que reconocen derechos susceptibles de amparo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Puede interponerse sin necesidad de agotar la vía judicial procedente</mark></span>El <span class=\"ref-norma\">art. 43 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán dar lugar al recurso de amparo una vez que se haya agotado la vía judicial procedente\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 34 — Tramitación del recurso","q":[{"i":"7-12","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de _______ remita las actuaciones o testimonio de ellas.","o":["Diez días.","Veinte días.","Un mes.","Tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 51.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.\"</span>."},{"i":"7-ia-7053","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del recurso de inconstitucionalidad. Admitida a trámite la demanda, la personación y la formulación de alegaciones deberán hacerse en el plazo de quince días, transcurrido el cual el Tribunal dictará sentencia en el de:","o":["diez días, salvo que, mediante resolución motivada, estime necesario un plazo más amplio que no podrá exceder de treinta días.","quince días, salvo que se solicite una prórroga de un mes, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","treinta días, sin posibilidad de ampliación.","diez días, sin posibilidad de ampliación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez días, salvo que, mediante resolución motivada, estime necesario un plazo más amplio que no podrá exceder de treinta días</mark></span>El <span class=\"ref-norma\">art. 34.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"transcurrido el cual el Tribunal dictará sentencia en el de diez, salvo que\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7062","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El Tribunal Constitucional dará traslado de la cuestión de inconstitucionalidad al Congreso, al Senado, al Fiscal General del Estado y al Gobierno. Concluido el plazo de alegaciones, el Tribunal dictará sentencia en el plazo de:","o":["diez días, salvo que se prorrogue por quince días, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","treinta días, sin posibilidad de ampliación.","quince días, sin posibilidad de ampliación.","quince días, salvo que estime necesario, mediante resolución motivada, un plazo más amplio que no podrá exceder de treinta días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">quince días, salvo que estime necesario, mediante resolución motivada, un plazo más amplio que no podrá exceder de treinta días</mark></span>El <span class=\"ref-norma\">art. 37.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Concluido éste, el Tribunal dictará sentencia en el plazo de quince días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 47 — Comparecencia y Ministerio Fiscal","q":[{"i":"7-13","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Recurso de amparo Constitucional. La Procedencia e Interposición del Recurso de amparo Constitucional. Podrán comparecer en el proceso de amparo Constitucional, con el carácter de demandado o con el de _______ las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.","o":["Demandante.","Coadyuvante.","Interesado.","Todos son correctos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Coadyuvante</mark></span>Demandante e «interesado» no son las figuras que cita el artículo. Según el <span class=\"ref-norma\">art. 47.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Podrán comparecer en el proceso de amparo constitucional, con el carácter de demandado o con el de coadyuvante, las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo\"</span> (verificado con el texto del temario)."},{"i":"7-121","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Podrán comparecer en el proceso de amparo constitucional, con el carácter de ___________, las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.","o":["demandado.","Coadyuvante.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 47.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Podrán comparecer en el proceso de amparo constitucional, con el carácter de demandado o con el de coadyuvante, las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.\"</span>."},{"i":"7-ia-7173","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Comparecencia en el amparo. Podrán comparecer en el proceso de amparo constitucional, con el carácter de demandado o con el de coadyuvante:","o":["únicamente las personas favorecidas por la decisión impugnada, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","las Administraciones Públicas afectadas.","las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.","cualquier persona física o jurídica."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo</mark></span>El <span class=\"ref-norma\">art. 47.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7174","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Comparecencia en el amparo. El Ministerio Fiscal intervendrá en todos los procesos de amparo, en defensa de la legalidad, de los derechos de los ciudadanos y:","o":["del orden constitucional.","del interés público tutelado por la Ley.","de la independencia judicial, sin perjuicio de lo dispuesto en el Derecho nacional.","de la seguridad jurídica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del interés público tutelado por la Ley</mark></span>El <span class=\"ref-norma\">art. 47.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la Ley\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · LO 2/1979 del Tribunal Constitucional — R1 a R9","q":[{"i":"7-14","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tribunal Constitucional, su organización y Atribuciones. Sobre la cuestión de jurisdicción o competencia el Tribunal Constitucional: Señale la correcta.","o":["En ningún caso se podrá pronunciar.","El conocimiento no se podrá promover en cuestión de Jurisdicción.","El conocimiento se podrá promover sobre la competencia.","Se podrá pronunciar sobre la competencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se podrá pronunciar sobre la competencia</mark></span>El <span class=\"ref-norma\">art. 4.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"En ningún caso se podrá promover cuestión de jurisdicción o competencia al Tribunal Constitucional. El Tribunal Constitucional delimitará el ámbito de su jurisdicción y adoptará cuantas medidas sean necesarias para preservarla, incluyendo la declaración de nulidad de aquellos actos o resoluciones que la menoscaben; asimismo podrá apreciar de oficio o a instancia de parte su competencia o incompetencia.\"</span>."},{"i":"7-19","p":"Ley Orgánica del Tribunal Constitucional. Recurso de amparo. ¿En qué plazo deberán presentarse las peticiones de indemnización?","o":["En el plazo de tres meses desde que la sentencia devenga firme.","En el plazo de seis meses desde que se notifique la sentencia.","En el plazo de un año a partir de la publicación de la sentencia.","En el plazo de dos años desde que se publique la sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el plazo de un año a partir de la publicación de la sentencia</mark></span>El plazo es de un año desde la PUBLICACIÓN de la sentencia (no desde que sea firme). Según el <span class=\"ref-norma\">art. 58.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las peticiones de indemnización [...] deberán presentarse dentro del plazo de un año a partir de la publicación de la sentencia del Tribunal Constitucional\"</span> (verificado con el texto del temario)."},{"i":"7-66","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué órgano jurisdiccional entenderá de los conflictos en defensa de la autonomía local?","o":["El Tribunal Constitucional.","La Audiencia Provincial.","El Tribunal Superior de Justicia.","El Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 2.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"d) De los conflictos entre los órganos constitucionales del Estado. d) bis. De los conflictos en defensa de la autonomía local. e) De la declaración sobre la constitucionalidad de los tratados internacionales.\"</span>."},{"i":"7-72","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo constitucional. El conocimiento de los recursos de amparo constitucional corresponde a:","o":["Las Salas del Tribunal Constitucional y, en su caso, a las Secciones.","El Pleno, entre otros.","Las Salas del Tribunal Constitucional, exclusivamente.","Las respuestas A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Salas del Tribunal Constitucional y, en su caso, a las Secciones</mark></span>No es «exclusivamente» de las Salas: también las Secciones, en su caso. Según el <span class=\"ref-norma\">art. 48 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El conocimiento de los recursos de amparo constitucional corresponde a las Salas del Tribunal Constitucional y, en su caso, a las Secciones\"</span> (verificado con el texto del temario)."},{"i":"7-104","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué órgano elabora los presupuestos del Tribunal Constitucional?","o":["El Pleno.","La Gran Sala.","La Sala.","La Sección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Pleno</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>."},{"i":"7-145","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. En las violaciones originadas por el Gobierno o sus autoridades o funcionarios, el plazo para interponer el recurso de amparo constitucional será el de los:","o":["Treinta días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","Veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","Veinte días siguientes a la fecha de la resolución recaída en el previo proceso judicial.","Tres meses siguientes a la notificación de la resolución recaída en el previo proceso judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial</mark></span>El <span class=\"ref-norma\">art. 43.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo constitucional será el de los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial.\"</span>. 20 días (Gobierno) · 30 días (órganos judiciales) · 3 meses (actos sin valor de Ley de las Cortes y Asambleas). <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado R5 en tu temario)</em>"},{"i":"7-ia-7012","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. Respecto a la jurisdicción del Tribunal Constitucional, en ningún caso se podrá promover:","o":["recurso de amparo contra sus resoluciones.","cuestión de jurisdicción o competencia al Tribunal Constitucional.","cuestión de inconstitucionalidad contra sus reglamentos, en los términos que establezca el propio Reglamento.","cuestión prejudicial ante el Tribunal Supremo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuestión de jurisdicción o competencia al Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 4.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En ningún caso se podrá promover cuestión de jurisdicción o competencia al Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7016","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Composición. El Tribunal Constitucional está integrado por doce miembros, con el título de:","o":["Vocales del Tribunal Constitucional.","Magistrados del Tribunal Constitucional.","Consejeros del Tribunal Constitucional, sin perjuicio de lo dispuesto en el Derecho nacional.","Jueces del Tribunal Constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Magistrados del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 5 de LOTC</span> dispone: <span class=\"ref-concepto\">\"está integrado por doce miembros, con el título de Magistrados del Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7035","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Distribución de asuntos. La distribución de asuntos entre las Salas del Tribunal se efectuará según un turno establecido por:","o":["el Presidente a propuesta del Pleno.","el Vicepresidente.","el Pleno a propuesta de su Presidente.","el Consejo General del Poder Judicial, salvo que el Estado miembro afectado disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Pleno a propuesta de su Presidente</mark></span>El <span class=\"ref-norma\">art. 12 de LOTC</span> dispone: <span class=\"ref-concepto\">\"según un turno establecido por el Pleno a propuesta de su Presidente\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7047","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Recurso de inconstitucionalidad. El recurso de inconstitucionalidad contra las Leyes, disposiciones normativas o actos con fuerza de Ley podrá promoverse:","o":["a partir de su entrada en vigor.","a partir de su sanción por el Rey.","a partir de su publicación oficial.","a partir de su aprobación por las Cortes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a partir de su publicación oficial</mark></span>El <span class=\"ref-norma\">art. 31 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrá promoverse a partir de su publicación oficial\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7153","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. En las sentencias recaídas en cuestiones de inconstitucionalidad, el Tribunal Constitucional lo comunicará inmediatamente al órgano judicial competente para la decisión del proceso. Dicho órgano:","o":["publicará la sentencia en el «Boletín Oficial del Estado».","remitirá la sentencia al Consejo General del Poder Judicial.","notificará la sentencia constitucional a las partes.","dictará sentencia en el plazo de diez días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">notificará la sentencia constitucional a las partes</mark></span>El <span class=\"ref-norma\">art. 38.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Dicho órgano notificará la sentencia constitucional a las partes\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7164","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. En los casos de violaciones de derechos originadas por el Gobierno o sus autoridades, el plazo para interponer el recurso de amparo será el de:","o":["los treinta días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","los tres meses siguientes a la notificación de la resolución judicial.","los diez días siguientes a la notificación de la resolución judicial.","los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial</mark></span>El <span class=\"ref-norma\">art. 43.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo constitucional será el de los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7175","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del amparo. El conocimiento de los recursos de amparo constitucional corresponde:","o":["a las Salas del Tribunal Constitucional y, en su caso, a las Secciones.","al Pleno del Tribunal Constitucional.","a las Secciones, con revisión del Pleno, en los términos que establezca el propio Reglamento.","a la Sala Primera exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a las Salas del Tribunal Constitucional y, en su caso, a las Secciones</mark></span>El <span class=\"ref-norma\">art. 48 de LOTC</span> dispone: <span class=\"ref-concepto\">\"corresponde a las Salas del Tribunal Constitucional y, en su caso, a las Secciones\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7200","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Indemnización por la suspensión. Las peticiones de indemnización por la suspensión, que se sustanciarán por el trámite de los incidentes, deberán presentarse dentro del plazo de:","o":["seis meses a partir de la publicación de la sentencia.","tres meses a partir de la notificación de la sentencia, en los términos que establezca el propio Reglamento.","dos años a partir de la publicación de la sentencia.","un año a partir de la publicación de la sentencia del Tribunal Constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un año a partir de la publicación de la sentencia del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 58.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"deberán presentarse dentro del plazo de un año a partir de la publicación de la sentencia del Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"General / Derechos y Deberes Fundamentales (CE)","q":[{"i":"7-17","p":"Ley Orgánica del Tribunal Constitucional. La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de:","o":["Las cuestiones prejudiciales que se le planteen por el orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de esta.","Las cuestiones incidentales de potencias entre el orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de esta.","Las opciones A y B son correctas.","Las opciones A y B son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones A y B son incorrectas</mark></span>Son cuestiones NO pertenecientes al orden constitucional; A y B dicen lo contrario o están alteradas. Según el <span class=\"ref-norma\">art. 3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta\"</span> (verificado con el texto del temario)."},{"i":"7-20","p":"Ley Orgánica del Tribunal Constitucional. Son susceptibles de declaración de inconstitucionalidad entre otros:","o":["Los Tratados internacionales.","Los Reglamentos de las Cámaras y de las Cortes Generales.","Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>Las tres son susceptibles de declaración de inconstitucionalidad. Según el <span class=\"ref-norma\">art. 27.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Son susceptibles de declaración de inconstitucionalidad: [...] c) Los Tratados Internacionales. d) Los Reglamentos de las Cámaras y de las Cortes Generales. [...] f) Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas\"</span> (verificado con el texto del temario)."},{"i":"7-21","p":"Ley Orgánica del Tribunal Constitucional. ¿De qué forma se integran los presupuestos del Tribunal Constitucional en los Presupuestos Generales del Estado?","o":["Se integra como una sección independiente dentro de los Presupuestos Generales del Estado.","Se integra como una sección dependiente dentro de los Presupuestos Generales del Estado.","Se integra de forma genérica en los Presupuestos Generales del Estado.","No se encuentran integrados en los Presupuestos Generales del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se integra como una sección independiente dentro de los Presupuestos Generales del Estado</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>."},{"i":"7-24","p":"Ley Orgánica del Tribunal Constitucional. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo _______ remita las actuaciones o testimonio de ellas.","o":["que no podrá exceder de diez días.","que no podrá exceder de veinte días.","Entre diez y veinte días.","Entre diez y quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que no podrá exceder de diez días</mark></span>El <span class=\"ref-norma\">art. 51.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.\"</span>."},{"i":"7-27","p":"Ley Orgánica del Tribunal Constitucional. ¿Cómo se efectuará la votación para la elección del Presidente del Tribunal Constitucional?","o":["La votación será secreta.","La votación será pública.","La votación será secreta, siendo solo accesos a los Magistrados que participen en la misma.","No existe tal votación, puesto que es elegido por el Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La votación será secreta</mark></span>El <span class=\"ref-norma\">art. 9.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento.\"</span>."},{"i":"7-49","p":"Ley Orgánica del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina: Señale la opción incorrecta.","o":["De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de las de éstas entre sí.","De los conflictos constitucionales en materia electoral.","De la declaración sobre la constitucionalidad de los Tratados Internacionales.","De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De los conflictos constitucionales en materia electoral</mark></span>En el art. 2.1 no figuran los «conflictos constitucionales en materia electoral». Según el <span class=\"ref-norma\">art. 2.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"De la declaración sobre la constitucionalidad de los tratados internacionales\"</span> (verificado con el texto del temario)."},{"i":"7-50","p":"Ley Orgánica del Tribunal Constitucional. ¿Es renovable el mandato del Presidente del Tribunal Constitucional?","o":["No, solo podrá ser elegido una sola vez.","Sí, aunque sólo se podrá re-elegir por una sola vez.","Sí, es renovable hasta que se alcance el límite de edad para ejercer como Magistrado.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sí, aunque sólo se podrá re-elegir por una sola vez.</mark></span> El <span class=\"ref-norma\">art. 9.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El nombre del elegido se elevará al Rey para su nombramiento por un período de tres años, expirado el cual podrá ser reelegido por una sola vez.\"</span> TEST 4"},{"i":"7-89","p":"Ley Orgánica del Tribunal Constitucional. De la tramitación de los recursos de amparo constitucional. En el proceso por recurso de amparo, la Sala, o en su caso la Sección, pronunciará la sentencia que proceda en el plazo de diez días a partir del día señalado para la vista o deliberación.","o":["Diez días.","Tres días.","Cinco días.","Siete días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 52.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sala, o en su caso la Sección, pronunciará la sentencia que proceda en el plazo de 10 días a partir del día señalado para la vista o deliberación.\"</span>."}]},{"a":"Artículo 44 — Amparo frente a órganos judiciales","q":[{"i":"7-25","p":"Ley Orgánica del Tribunal Constitucional. Las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial, podrán dar lugar a este recurso siempre que se cumplan los requisitos siguientes: Señale la opción correcta.","o":["Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquéllas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional.","Que se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial.","Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 44.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquellas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional. c) Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.\"</span>. La opción C original («sin haber denunciado…») invertía el requisito: hay que haber denunciado formalmente la vulneración."}]},{"a":"Artículo 32 — Legitimación","q":[{"i":"7-34","p":"Ley Orgánica del Tribunal Constitucional. Están legitimados para el ejercicio del recurso de inconstitucionalidad cuando se trate de Estatutos de Autonomía y demás Leyes del Estado, orgánicas o en cualesquiera de sus formas, y disposiciones normativas y actos del Estado o de las Comunidades Autónomas con fuerza de ley, Tratados Internacionales y Reglamentos de las Cámaras y de las Cortes Generales:","o":["El Consejo de Ministros.","50 Diputados.","60 Senadores.","80 miembros de las Cortes Generales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">50 Diputados</mark></span>El <span class=\"ref-norma\">art. 32.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"a) El Presidente del Gobierno. b) El Defensor del Pueblo. c) Cincuenta Diputados. d) Cincuenta Senadores.\"</span>."},{"i":"7-95","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De los procedimientos de declaración de inconstitucionalidad. Son susceptibles de declaración de inconstitucionalidad:","o":["Los Estatutos de Autonomía y las demás Leyes orgánicas.","Los Reglamentos de las Cámaras y de las Cortes Generales.","Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 50.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso solamente cuando concurran todos los siguientes requisitos\"</span>."},{"i":"7-ia-7048","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación para el recurso de inconstitucionalidad. Están legitimados para el ejercicio del recurso de inconstitucionalidad contra Estatutos de Autonomía y demás Leyes del Estado:","o":["el Presidente del Gobierno, el Defensor del Pueblo, cuarenta Diputados y cuarenta Senadores.","el Presidente del Gobierno, el Defensor del Pueblo, cincuenta Diputados y cincuenta Senadores.","el Presidente del Gobierno, el Fiscal General del Estado, cincuenta Diputados y cincuenta Senadores.","el Gobierno, el Defensor del Pueblo, cincuenta Diputados y veinticinco Senadores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Presidente del Gobierno, el Defensor del Pueblo, cincuenta Diputados y cincuenta Senadores</mark></span>El <span class=\"ref-norma\">art. 32.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) El Presidente del Gobierno. b) El Defensor del Pueblo. c) Cincuenta Diputados. d) Cincuenta Senadores\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7049","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación para el recurso de inconstitucionalidad. Para el recurso de inconstitucionalidad contra Leyes del Estado que puedan afectar a su propio ámbito de autonomía, están también legitimados:","o":["los órganos colegiados ejecutivos y las Asambleas de las Comunidades Autónomas, previo acuerdo adoptado al efecto.","los Presidentes de las Comunidades Autónomas, sin necesidad de acuerdo, salvo que el Estado miembro afectado disponga otra cosa.","los Parlamentos autonómicos, por mayoría absoluta.","las Comunidades Autónomas a través del Defensor del Pueblo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los órganos colegiados ejecutivos y las Asambleas de las Comunidades Autónomas, previo acuerdo adoptado al efecto</mark></span>El <span class=\"ref-norma\">art. 32.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"están también legitimados los órganos colegiados ejecutivos y las Asambleas de las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · LO 1/1982 honor, intimidad e imagen — R10 a R13","q":[{"i":"7-35","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Señale la opción incorrecta.","o":["La existencia de prejuicio no se presumirá aunque se acredite la intromisión ilegítima.","Tendrá la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 7 de esta ley, la utilización del delito por el condenado en sentencia penal firme para conseguir notoriedad pública u obtener provecho económico, o la divulgación de datos falsos sobre los hechos delictivos, cuando ello suponga el menoscabo de la dignidad de las víctimas.","El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, garantizado en el artículo 18 de la Constitución, será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en esta Ley Orgánica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La existencia de prejuicio no se presumirá aunque se acredite la intromisión ilegítima</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La existencia de perjuicio se presumirá siempre que se acredite la intromisión ilegítima.\"</span>. La ley dice que el perjuicio se PRESUME siempre que se acredite la intromisión."},{"i":"7-48","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Señale la opción incorrecta.","o":["El consentimiento otorgado para la intromisión ilegítima será revocable en cualquier momento, sin que proceda indemnización alguna por las acciones realizadas hasta ese momento.","El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, garantizado en el artículo 18 de la Constitución, será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en esta Ley Orgánica.","El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","Tendrá la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 7 de esta Ley, el emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El consentimiento otorgado para la intromisión ilegítima será revocable en cualquier momento, sin que proceda indemnización alguna por las acciones realizadas hasta ese momento</mark></span>El <span class=\"ref-norma\">art. 2.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento a que se refiere el párrafo anterior será revocable en cualquier momento, pero habrán de indemnizarse en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas.\"</span>. El consentimiento es revocable en cualquier momento, pero con indemnización de los daños y perjuicios causados (incluidas las expectativas justificadas)."},{"i":"7-79","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Disposiciones generales. El consentimiento de los menores e incapaces debe prestarse:","o":["En todo caso, por quienes ejerzan la patria potestad de forma oral o escrita.","Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","En todo caso, mediante escrito por su representante legal.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.\"</span>."},{"i":"7-103","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Disposiciones generales. Señale la INCORRECTA.","o":["El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible.","El consentimiento de los menores e incapaces deberá prestarse por el juez competente, aunque su grado de madurez lo permita, de acuerdo con la legislación civil.","El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien esta haya designado a tal efecto en su testamento. La designación puede recaer en una persona jurídica.","El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El consentimiento de los menores e incapaces deberá prestarse por el juez competente, aunque su grado de madurez lo permita, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.\"</span>."},{"i":"7-137","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Disposiciones generales. El consentimiento de los menores e incapaces deberá prestarse:","o":["En todo caso, por quienes ejerzan la patria potestad o la tutela por escrito.","Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","En todo caso, mediante escrito por su representante legal.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.\"</span>. La regla general es que los menores e incapaces con madurez suficiente consienten por sí mismos; el escrito del representante legal es para los restantes casos."},{"i":"7-ia-7303","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Los derechos garantizados por la Ley han sido encuadrados por la doctrina jurídica entre los derechos de la personalidad, calificación de la que se desprende su carácter:","o":["renunciable.","transmisible.","irrenunciable.","prescriptible, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">irrenunciable</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"entre los derechos de la personalidad, calificación de la que obviamente se desprende el carácter de irrenunciable\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7315","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Consentimiento de menores e incapaces. El consentimiento de los menores e incapaces deberá prestarse por ellos mismos:","o":["en todo caso, con asistencia de sus representantes.","únicamente si han cumplido catorce años.","si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","únicamente mediante escrito autorizado por el Ministerio Fiscal, salvo que el Estado miembro afectado disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7343","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones transitorias. En tanto no sean desarrolladas las previsiones constitucionales sobre un procedimiento basado en los principios de preferencia y sumariedad, la tutela judicial de estos derechos se podrá recabar por cualquiera de los procedimientos establecidos en las Secciones II y III de la Ley:","o":["2/1979, de 3 de octubre, del Tribunal Constitucional.","1/2000, de 7 de enero, de Enjuiciamiento Civil.","62/1978, de 26 de diciembre, de Protección Jurisdiccional de los derechos fundamentales de la persona.","29/1998, de 13 de julio, reguladora de la jurisdicción contencioso-administrativa, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">62/1978, de 26 de diciembre, de Protección Jurisdiccional de los derechos fundamentales de la persona</mark></span>El <span class=\"ref-norma\">disp. transitoria segunda de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"por cualquiera de los procedimientos establecidos en las Secciones II y III de la Ley sesenta y dos/mil novecientos setenta y ocho\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 39 — Nulidad","q":[{"i":"7-37","p":"Ley Orgánica del Tribunal Constitucional. Cuando la sentencia declare la inconstitucionalidad:","o":["Declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.","Declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Reglamentos a los que deba extenderse por conexión o consecuencia.","Declarará igualmente la insalvabilidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia</mark></span>El <span class=\"ref-norma\">art. 39.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Cuando la sentencia declare la inconstitucionalidad, declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.\"</span>."},{"i":"7-ia-7155","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de la declaración de inconstitucionalidad. Cuando la sentencia declare la inconstitucionalidad, declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso:","o":["la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.","la de las disposiciones reglamentarias que los desarrollen, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","la de las resoluciones judiciales que los hayan aplicado.","la de toda la ley en la que se integren."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia</mark></span>El <span class=\"ref-norma\">art. 39.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7156","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de la declaración de inconstitucionalidad. El Tribunal Constitucional podrá fundar la declaración de inconstitucionalidad en la infracción de cualquier precepto constitucional:","o":["únicamente si ha sido invocado en el proceso.","únicamente si lo solicita el Ministerio Fiscal.","únicamente si se refiere a derechos fundamentales.","haya o no sido invocado en el curso del proceso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">haya o no sido invocado en el curso del proceso</mark></span>El <span class=\"ref-norma\">art. 39.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"haya o no sido invocado en el curso del\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 29 — Vías de la declaración","q":[{"i":"7-39","p":"Ley Orgánica del Tribunal Constitucional. La declaración de inconstitucionalidad podrá promoverse mediante:","o":["Acción de impugnación directa.","Recurso de inconstitucionalidad promovida por Jueces o Tribunales.","La cuestión de inconstitucionalidad promovida por Jueces o Tribunales.","La cuestión de inconstitucionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La cuestión de inconstitucionalidad promovida por Jueces o Tribunales</mark></span>El <span class=\"ref-norma\">art. 29.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La declaración de inconstitucionalidad podrá promoverse mediante: a) El recurso de inconstitucionalidad. b) La cuestión de inconstitucionalidad promovida por Jueces o Tribunales.\"</span>."},{"i":"7-ia-7044","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. La declaración de inconstitucionalidad podrá promoverse mediante:","o":["el recurso de amparo y la cuestión de inconstitucionalidad.","el recurso de inconstitucionalidad y la cuestión de inconstitucionalidad promovida por Jueces o Tribunales.","el recurso de inconstitucionalidad y el conflicto de competencia, en los términos que establezca el propio Reglamento.","la cuestión de inconstitucionalidad y el recurso previo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el recurso de inconstitucionalidad y la cuestión de inconstitucionalidad promovida por Jueces o Tribunales</mark></span>El <span class=\"ref-norma\">art. 29.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) El recurso de inconstitucionalidad. b) La cuestión de inconstitucionalidad promovida por Jueces o Tribunales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7045","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. La desestimación, por razones de forma, de un recurso de inconstitucionalidad contra una Ley no será obstáculo para que la misma Ley pueda ser objeto:","o":["de una cuestión de inconstitucionalidad con ocasión de su aplicación en otro proceso.","de un nuevo recurso de inconstitucionalidad en el mismo año, salvo que el Estado miembro afectado disponga otra cosa.","de un recurso de amparo.","de un conflicto en defensa de la autonomía local."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de una cuestión de inconstitucionalidad con ocasión de su aplicación en otro proceso</mark></span>El <span class=\"ref-norma\">art. 29.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"puedan ser objeto de una cuestión de inconstitucionalidad con ocasión de su aplicación en otro proceso\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 56 — Suspensión y medidas cautelares ✱ R8","q":[{"i":"7-42","p":"Ley Orgánica del Tribunal Constitucional. La interposición del recurso de amparo:","o":["Suspenderá los efectos del acto o sentencia impugnados.","No suspenderá los efectos del acto o sentencia impugnados.","No obstante, cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala, o la Sección en el supuesto del artículo 52.2, de oficio o a instancia del recurrente, podrá disponer la suspensión, total o parcial, de sus efectos, siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona.","Las opciones A y B son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No obstante, cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala, o la Sección en el supuesto del artículo 52.2, de oficio o a instancia del recurrente, podrá disponer la suspensión, total o parcial, de sus efectos, siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona</mark></span>El <span class=\"ref-norma\">art. 56.1 y 2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"1. La interposición del recurso de amparo no suspenderá los efectos del acto o sentencia impugnados. 2. Ello no obstante, cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala, o la Sección en el supuesto del artículo 52.2, de oficio o a instancia del recurrente, podrá disponer la suspensión, total o parcial, de sus efectos, siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona.\"</span>. La regla general es que el recurso NO suspende los efectos; la suspensión es excepcional (art. 56.2)."},{"i":"7-109","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Recurso de amparo. ¿En qué supuestos se podrá adoptar la suspensión y las medidas cautelares y provisionales en la resolución de la admisión a trámite?","o":["En los supuestos de perturbación grave de los derechos del interesado.","En los supuestos de urgencia excepcional.","En los supuestos en que se satisfaga o aporte fianza.","En el supuesto en que se obtenga la oportuna fianza."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En los supuestos de urgencia excepcional</mark></span>Según el <span class=\"ref-norma\">art. 56.6 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"En supuestos de urgencia excepcional, la adopción de la suspensión y de las medidas cautelares y provisionales podrá efectuarse en la resolución de la admisión a trámite\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7192","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. La interposición del recurso de amparo:","o":["suspenderá los efectos del acto o sentencia impugnados.","suspenderá los efectos solo si lo solicita el recurrente, en los términos que establezca el propio Reglamento.","suspenderá los efectos hasta la admisión a trámite.","no suspenderá los efectos del acto o sentencia impugnados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no suspenderá los efectos del acto o sentencia impugnados</mark></span>El <span class=\"ref-norma\">art. 56.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La interposición del recurso de amparo no suspenderá los efectos del acto o sentencia impugnados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7193","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. Cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala podrá disponer la suspensión, siempre y cuando:","o":["el recurrente preste caución suficiente.","el Ministerio Fiscal informe favorablemente.","la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona.","el acto impugnado no afecte a una Administración Pública, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona</mark></span>El <span class=\"ref-norma\">art. 56.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7194","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. El incidente de suspensión se sustanciará con audiencia de las partes y del Ministerio Fiscal, por un plazo común que no excederá de:","o":["cinco días.","tres días.","diez días.","quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres días</mark></span>El <span class=\"ref-norma\">art. 56.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"por un plazo común que no excederá de tres días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7195","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. La suspensión u otra medida cautelar en el amparo podrá pedirse:","o":["en cualquier tiempo, antes de haberse pronunciado la sentencia o decidirse el amparo de otro modo.","únicamente en la demanda de amparo.","únicamente tras la admisión a trámite.","únicamente en el plazo de diez días desde la admisión, sin perjuicio de lo dispuesto en el Derecho nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en cualquier tiempo, antes de haberse pronunciado la sentencia o decidirse el amparo de otro modo</mark></span>El <span class=\"ref-norma\">art. 56.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La suspensión u otra medida cautelar podrá pedirse en cualquier tiempo, antes de haberse pronunciado la sentencia\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7196","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. La Sala o la Sección podrá condicionar la suspensión de la ejecución y la adopción de las medidas cautelares a la satisfacción por el interesado de:","o":["una declaración jurada de responsabilidad.","el informe favorable del Ministerio Fiscal.","la prestación de aval bancario por el importe del acto, en los términos que establezca el propio Reglamento.","la oportuna fianza suficiente para responder de los daños y perjuicios que pudieren originarse."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la oportuna fianza suficiente para responder de los daños y perjuicios que pudieren originarse</mark></span>El <span class=\"ref-norma\">art. 56.5 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a la satisfacción por el interesado de la oportuna fianza suficiente para responder de los daños y perjuicios que pudieren originarse\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7197","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. En supuestos de urgencia excepcional, la adopción de la suspensión y de las medidas cautelares podrá efectuarse en la resolución de la admisión a trámite. Dicha adopción podrá ser impugnada en el plazo de:","o":["tres días desde su notificación, por el recurrente.","diez días desde su notificación, por el Ministerio Fiscal, salvo que el Estado miembro afectado disponga otra cosa.","cinco días desde su notificación, por el Ministerio Fiscal y demás partes personadas.","quince días desde su notificación, por las partes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cinco días desde su notificación, por el Ministerio Fiscal y demás partes personadas</mark></span>El <span class=\"ref-norma\">art. 56.6 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrá ser impugnada en el plazo de cinco días desde su notificación, por el Ministerio Fiscal y demás partes personadas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 8 — Las Secciones","q":[{"i":"7-51","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. En caso de que se admita una causa por el Tribunal Constitucional, ¿quién podrá asumir el conocimiento del asunto de que se trate?","o":["El Pleno.","El Pleno, aunque podrá deferir a una Sala.","El Pleno, aunque podrá deferir a una Sala, y ésta a su vez en una Sección.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Pleno, aunque podrá deferir a una Sala</mark></span>El <span class=\"ref-norma\">art. 8.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"En el caso de admisión, el Pleno podrá deferir a la Sala que corresponda el conocimiento del asunto de que se trate, en los términos previstos en esta ley.\"</span>."},{"i":"7-101","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué asuntos podrán asumir las Secciones en cuanto a su conocimiento y resolución?","o":["Las cuestiones de inconstitucionalidad.","Los asuntos de amparo.","Los conflictos de competencia.","Las impugnaciones previstas en la Constitución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los asuntos de amparo</mark></span>Según el <span class=\"ref-norma\">art. 8.3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Podrá corresponder también a las Secciones el conocimiento y resolución de aquellos asuntos de amparo que la Sala correspondiente les defiera\"</span> (verificado con el texto del temario)."},{"i":"7-138","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Para el despacho ordinario y la decisión o propuesta, según proceda, sobre la admisibilidad o inadmisibilidad de procesos constitucionales, el Pleno y las Salas constituirán Secciones compuestas por:","o":["El Presidente y un Magistrado.","El Presidente o quien le sustituya y dos Magistrados.","El Presidente, el Vicepresidente y un Magistrado.","El Presidente, el Vicepresidente y dos Magistrados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Presidente o quien le sustituya y dos Magistrados</mark></span>El <span class=\"ref-norma\">art. 8.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"el Pleno y las Salas constituirán Secciones compuestas por el respectivo Presidente o quien le sustituya y dos Magistrados.\"</span>."},{"i":"7-ia-7022","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Secciones. Para el despacho ordinario y la decisión o propuesta sobre la admisibilidad o inadmisibilidad de procesos constitucionales, el Pleno y las Salas constituirán Secciones compuestas por el respectivo Presidente o quien le sustituya y:","o":["tres Magistrados.","un Magistrado.","cuatro Magistrados.","dos Magistrados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos Magistrados</mark></span>El <span class=\"ref-norma\">art. 8.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Secciones compuestas por el respectivo Presidente o quien le sustituya y dos Magistrados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7023","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Secciones. Se dará cuenta al Pleno de las propuestas de admisión o inadmisión de asuntos de su competencia. En el caso de admisión, el Pleno podrá:","o":["deferir a las Secciones el conocimiento del asunto.","remitir el asunto al Consejo General del Poder Judicial, conforme al procedimiento que se establezca reglamentariamente.","deferir a la Sala que corresponda el conocimiento del asunto de que se trate.","someter el asunto a informe del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">deferir a la Sala que corresponda el conocimiento del asunto de que se trate</mark></span>El <span class=\"ref-norma\">art. 8.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"el Pleno podrá deferir a la Sala que corresponda el\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 41 — Derechos amparables","q":[{"i":"7-57","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Qué protección se le otorga a la objeción de conciencia reconocida en el artículo 30 de la Constitución?","o":["Son susceptibles de cuestión de constitucionalidad.","Son susceptibles de revisión constitucional.","Son susceptibles de amparo constitucional.","Son susceptibles de recurso de constitucionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Son susceptibles de amparo constitucional</mark></span>El <span class=\"ref-norma\">art. 41.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Los derechos y libertades reconocidos en los artículos catorce a veintinueve de la Constitución serán susceptibles de amparo constitucional, en los casos y formas que esta Ley establece, sin perjuicio de su tutela general encomendada a los Tribunales de Justicia. Igual protección será aplicable a la objeción de conciencia reconocida en el artículo treinta de la Constitución.\"</span>."},{"i":"7-122","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Los derechos y libertades reconocidos en los artículos 14 a 29 de la Constitución serán susceptibles de ____________, en los casos y formas que esta ley establece, sin perjuicio de su tutela general encomendada a los Tribunales de Justicia. Igual protección será aplicable a la objeción de conciencia reconocida en el artículo 530 de la Constitución.","o":["de amparo constitucional.","de amparo común.","de protección estatal.","de recurso judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de amparo constitucional</mark></span>El <span class=\"ref-norma\">art. 41.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Los derechos y libertades reconocidos en los artículos catorce a veintinueve de la Constitución serán susceptibles de amparo constitucional, en los casos y formas que esta Ley establece, sin perjuicio de su tutela general encomendada a los Tribunales de Justicia. Igual protección será aplicable a la objeción de conciencia reconocida en el artículo treinta de la Constitución.\"</span>."},{"i":"7-ia-7159","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedencia del recurso de amparo. Los derechos y libertades reconocidos en los artículos catorce a veintinueve de la Constitución serán susceptibles de amparo constitucional, y la misma protección será aplicable a:","o":["la objeción de conciencia reconocida en el artículo treinta de la Constitución.","el derecho de propiedad reconocido en el artículo treinta y tres de la Constitución.","el derecho al trabajo reconocido en el artículo treinta y cinco de la Constitución.","la libertad de empresa reconocida en el artículo treinta y ocho de la Constitución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la objeción de conciencia reconocida en el artículo treinta de la Constitución</mark></span>El <span class=\"ref-norma\">art. 41.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Igual protección será aplicable a la objeción de conciencia reconocida en el artículo treinta de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7160","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedencia del recurso de amparo. El recurso de amparo constitucional protege frente a las violaciones de los derechos y libertades originadas por disposiciones, actos jurídicos, omisiones o simple vía de hecho de los poderes públicos del Estado, las Comunidades Autónomas y demás entes públicos de carácter territorial, corporativo o institucional, así como:","o":["de las personas privadas que gestionen servicios públicos.","de los partidos políticos y sindicatos.","de las empresas concesionarias de servicios.","de sus funcionarios o agentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de sus funcionarios o agentes</mark></span>El <span class=\"ref-norma\">art. 41.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"así como de sus funcionarios o agentes\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 52 — Vista y sentencia","q":[{"i":"7-77","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo. Recibidas las actuaciones y transcurrido el tiempo de emplazamiento: señale la INCORRECTA.","o":["La Sala dará vista de las mismas a quien promovió el amparo.","La vista será por plazo común que no pueda exceder de veinte días.","La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional.","Durante el plazo establecido podrán presentarse los alegaciones procedentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 52.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala dará vista de las mismas a quien promovió el amparo, a los personados en el proceso, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal. La vista será por plazo común que no podrá exceder de veinte días, y durante él podrán presentarse las alegaciones procedentes.\"</span>."},{"i":"7-127","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Cuándo podrá la Sala deferir la resolución de un recurso de amparo a favor de una de sus Secciones?","o":["Cuando el asunto no goce de una especial trascendencia, a tenor de su importancia para la interpretación de la Constitución.","Cuando su resolución no revista especial complejidad a la vista de lo solicitado y los derechos implicados.","Cuando dicha Sección haya resuelto con anterioridad un recurso con identidad sustantiva.","Cuando para su resolución sea aplicable la doctrina consolidada del Tribunal Constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando para su resolución sea aplicable la doctrina consolidada del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 52.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala podrá deferir la resolución del recurso, cuando para su resolución sea aplicable doctrina consolidada del Tribunal Constitucional, a una de sus Secciones\"</span>."},{"i":"7-131","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo. Recibidas las actuaciones y transcurrido el tiempo de emplazamiento: señale la INCORRECTA.","o":["La Sala dará vista de las mismas a quien promovió el amparo.","La vista será por plazo común que no podrá exceder de veinte días.","La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional.","Durante el plazo establecido podrán presentarse las alegaciones procedentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional</mark></span>La vista no se da al Tribunal Constitucional: es la opción falsa. Según el <span class=\"ref-norma\">art. 52.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"la Sala dará vista de las mismas a quien promovió el amparo, a los personados en el proceso, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7185","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Vista en el amparo. Recibidas las actuaciones y transcurrido el tiempo de emplazamiento, la Sala dará vista de las mismas a quien promovió el amparo, a los personados, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal, por plazo común que no podrá exceder de:","o":["diez días.","quince días.","veinte días.","treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">veinte días</mark></span>El <span class=\"ref-norma\">art. 52.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La vista será por plazo común que no podrá exceder de veinte días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7187","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Vista en el amparo. La Sala, o en su caso la Sección, pronunciará la sentencia que proceda en el plazo de:","o":["10 días a partir del día señalado para la vista o deliberación.","15 días a partir del día señalado para la vista o deliberación, en los términos que establezca el propio Reglamento.","20 días a partir del día señalado para la vista o deliberación.","30 días a partir del día señalado para la vista o deliberación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">10 días a partir del día señalado para la vista o deliberación</mark></span>El <span class=\"ref-norma\">art. 52.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"pronunciará la sentencia que proceda en el plazo de 10 días a partir del día señalado para la vista o deliberación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 1 — Naturaleza del Tribunal","q":[{"i":"7-120","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal Constitucional, como _______ de la Constitución, es independiente de los demás órganos constitucionales.","o":["intérprete preferido.","intérprete supremo.","intérprete absoluto.","intérprete constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">intérprete supremo</mark></span>Según el <span class=\"ref-norma\">art. 1.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Tribunal Constitucional, como intérprete supremo de la Constitución, es independiente de los demás órganos constitucionales y está sometido sólo a la Constitución y a la presente Ley Orgánica\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7001","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional, como intérprete supremo de la Constitución, es independiente de los demás órganos constitucionales y está sometido sólo:","o":["a la Constitución y a la presente Ley Orgánica.","a la Constitución y a las demás Leyes Orgánicas que lo regulen.","a la Constitución, a la Ley Orgánica y a la jurisprudencia del Tribunal Supremo.","a la Constitución y a los tratados internacionales ratificados por España."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Constitución y a la presente Ley Orgánica</mark></span>El <span class=\"ref-norma\">art. 1.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"es independiente de los demás órganos constitucionales y está sometido sólo a la Constitución y a la presente Ley Orgánica\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7002","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional es único en su orden y extiende su jurisdicción:","o":["a todo el territorio nacional y a los territorios de ultramar.","a las Comunidades Autónomas que no tengan Tribunal Superior.","a todo el territorio de la Unión Europea.","a todo el territorio nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a todo el territorio nacional</mark></span>El <span class=\"ref-norma\">art. 1.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Es único en su orden y extiende su jurisdicción a todo el territorio nacional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 35 — Planteamiento de la cuestión","q":[{"i":"7-ia-7055","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Antes de adoptar mediante auto su decisión definitiva sobre el planteamiento de la cuestión de inconstitucionalidad, el órgano judicial oirá a las partes y al Ministerio Fiscal para que en el plazo común e improrrogable de:","o":["15 días puedan alegar lo que deseen, en los términos que establezca el propio Reglamento.","5 días puedan alegar lo que deseen.","10 días puedan alegar lo que deseen.","30 días puedan alegar lo que deseen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">10 días puedan alegar lo que deseen</mark></span>El <span class=\"ref-norma\">art. 35.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en el plazo común e improrrogable de 10 días puedan alegar lo que deseen\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7056","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Oídas las partes y el Ministerio Fiscal, el juez resolverá sobre el planteamiento de la cuestión de inconstitucionalidad en el plazo de:","o":["cinco días.","tres días.","diez días.","quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres días</mark></span>El <span class=\"ref-norma\">art. 35.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"seguidamente y sin más trámite, el juez resolverá en el plazo de tres días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7057","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El auto por el que el juez decide plantear la cuestión de inconstitucionalidad:","o":["no será susceptible de recurso de ninguna clase, aunque la cuestión podrá ser intentada de nuevo en las sucesivas instancias o grados mientras no se llegue a sentencia firme.","será recurrible en apelación ante el órgano superior, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","será recurrible en reposición únicamente.","solo será recurrible ante el Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no será susceptible de recurso de ninguna clase, aunque la cuestión podrá ser intentada de nuevo en las sucesivas instancias o grados mientras no se llegue a sentencia firme</mark></span>El <span class=\"ref-norma\">art. 35.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Dicho auto no será susceptible de recurso de ninguna clase\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7058","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El planteamiento de la cuestión de inconstitucionalidad originará la suspensión provisional de las actuaciones en el proceso judicial hasta que el Tribunal Constitucional se pronuncie sobre su admisión. Producida ésta:","o":["el proceso judicial continuará su tramitación.","el proceso quedará archivado.","el proceso continuará, salvo en la fase de sentencia, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","el proceso judicial permanecerá suspendido hasta que el Tribunal Constitucional resuelva definitivamente sobre la cuestión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el proceso judicial permanecerá suspendido hasta que el Tribunal Constitucional resuelva definitivamente sobre la cuestión</mark></span>El <span class=\"ref-norma\">art. 35.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Producida ésta el proceso judicial permanecerá suspendido\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7065","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Señale la INCORRECTA sobre la cuestión de inconstitucionalidad:","o":["Puede plantearse en cualquier momento del procedimiento, incluso antes de que concluya la fase de prueba.","El órgano judicial oirá a las partes y al Ministerio Fiscal antes de decidir, en los términos que establezca el propio Reglamento.","Origina la suspensión provisional de las actuaciones en el proceso judicial.","El juez resuelve en tres días tras oír a las partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Puede plantearse en cualquier momento del procedimiento, incluso antes de que concluya la fase de prueba</mark></span>El <span class=\"ref-norma\">art. 35 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"El órgano judicial sólo podrá plantear la cuestión una vez concluso el procedimiento y dentro del plazo para dictar sentencia\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 37 — Tramitación ante el Tribunal Constitucional","q":[{"i":"7-ia-7060","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El Tribunal podrá rechazar, en trámite de admisión, mediante auto y sin otra audiencia que la del Fiscal General del Estado, la cuestión de inconstitucionalidad cuando:","o":["la norma impugnada sea anterior a la Constitución.","faltaren las condiciones procesales o fuere notoriamente infundada la cuestión suscitada.","la cuestión sea planteada por un órgano unipersonal, sin perjuicio de lo dispuesto en el Derecho nacional.","la norma impugnada haya sido derogada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">faltaren las condiciones procesales o fuere notoriamente infundada la cuestión suscitada</mark></span>El <span class=\"ref-norma\">art. 37.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"cuando faltaren las condiciones procesales o fuere notoriamente infundada la cuestión suscitada\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7061","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Publicada en el «Boletín Oficial del Estado» la admisión a trámite de la cuestión, quienes sean parte en el procedimiento judicial podrán personarse ante el Tribunal Constitucional dentro de:","o":["los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 15 días.","los 10 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 10 días, en los términos que establezca el propio Reglamento.","los 30 días siguientes a su publicación.","los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 10 días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 15 días</mark></span>El <span class=\"ref-norma\">art. 37.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán personarse ante el Tribunal Constitucional dentro de los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 15 días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la","q":[{"i":"7-ia-7301","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo de la Ley, los derechos al honor, a la intimidad personal y familiar y a la propia imagen tienen el rango de fundamentales conforme al precepto constitucional que, además, dispone que el respeto de tales derechos constituya:","o":["un límite al ejercicio de las libertades de expresión.","un límite al ejercicio del derecho de reunión.","un límite al ejercicio de la libertad ideológica.","un límite al derecho de información veraz exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un límite al ejercicio de las libertades de expresión</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"dispone que el respeto de tales derechos constituya un límite al ejercicio de las libertades de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7302","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo, en los casos en que exista protección penal de estos derechos:","o":["tendrá preferente aplicación la protección civil.","se aplicarán ambas protecciones de forma acumulativa, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","se aplicará la protección que elija el perjudicado.","tendrá ésta preferente aplicación, si bien la responsabilidad civil derivada del delito se deberá fijar de acuerdo con los criterios que esta ley establece."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tendrá ésta preferente aplicación, si bien la responsabilidad civil derivada del delito se deberá fijar de acuerdo con los criterios que esta ley establece</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Por ello en los casos que exista la protección penal tendrá ésta preferente aplicación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7304","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Respecto del consentimiento en la intromisión, el preámbulo señala que la ley exige que sea expreso y que, dada la índole particular de estos derechos, permite:","o":["que pueda ser revocado en el plazo de un año sin indemnización, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento.","que pueda ser revocado en cualquier momento, aunque con indemnización de los perjuicios que de la revocación se siguieren al destinatario del mismo.","que sea irrevocable una vez prestado.","que pueda ser tácito cuando sea habitual."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">que pueda ser revocado en cualquier momento, aunque con indemnización de los perjuicios que de la revocación se siguieren al destinatario del mismo</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"permite que pueda ser revocado en cualquier momento, aunque con indemnización de los perjuicios que de la revocación se siguieren al destinatario del mismo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7321","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Pluralidad de legitimados. Cuando sobrevivan varios parientes de los legitimados, cualquiera de ellos podrá ejercer:","o":["las acciones previstas para la protección de los derechos del fallecido.","las acciones únicamente si actúan todos conjuntamente.","las acciones únicamente si lo autoriza el Ministerio Fiscal, conforme al procedimiento que se establezca reglamentariamente.","las acciones únicamente el pariente de mayor edad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las acciones previstas para la protección de los derechos del fallecido</mark></span>El <span class=\"ref-norma\">art. 5.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cualquiera de ellos podrá ejercer las acciones previstas para la protección de los derechos\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7322","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Lesión antes del fallecimiento. Cuando el titular del derecho lesionado fallezca sin haber podido ejercitar por sí o por su representante legal las acciones por las circunstancias en que la lesión se produjo, las acciones podrán ejercitarse:","o":["únicamente por el Ministerio Fiscal, sin perjuicio de lo dispuesto en el Derecho nacional.","únicamente por los herederos.","únicamente por el cónyuge.","por las personas señaladas en el artículo cuarto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por las personas señaladas en el artículo cuarto</mark></span>El <span class=\"ref-norma\">art. 6.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"las referidas acciones podrán ejercitarse por las personas señaladas en el\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7323","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Lesión antes del fallecimiento. Las personas legitimadas podrán continuar la acción ya entablada por el titular del derecho lesionado:","o":["cuando renunciare.","cuando lo autorice el juez.","cuando falleciere.","cuando transcurran cuatro años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuando falleciere</mark></span>El <span class=\"ref-norma\">art. 6.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"podrán continuar la acción ya entablada por el titular del derecho lesionado cuando falleciere\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7342","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposición derogatoria. Según la disposición derogatoria de la Ley, quedan derogadas:","o":["todas las disposiciones anteriores que regulen el honor.","las disposiciones de rango inferior a la ley que regulen la intimidad, salvo que el Estado miembro afectado disponga otra cosa.","las disposiciones del Código Civil contrarias a la presente ley.","cuantas disposiciones de igual o inferior rango se opongan a lo previsto en la presente Ley Orgánica."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuantas disposiciones de igual o inferior rango se opongan a lo previsto en la presente Ley Orgánica</mark></span>El <span class=\"ref-norma\">disp. derogatoria de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Quedan derogadas cuantas disposiciones de igual o inferior rango se opongan a lo previsto en la presente Ley Orgánica\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
